//! The user's global standing rules as the clients' own instruction files
//! hold them: Claude Code's rules file and the block in Codex's AGENTS file.
//! Those files rank with the instructions an agent follows first, so only
//! rules the user stated and confirmed enter them, never observations,
//! inferences or project memories.

use super::{
    Memory,
    overview::{line, rule_groups},
    read::{group_order, standing_rule},
    schema::connect,
    selection::{ScopeFilter, Selection, candidates},
};
use anyhow::Result;
use std::path::Path;

/// First line of every generated file: marks it as user-memory's, so setup
/// never replaces a file the user wrote.
pub const GENERATED: &str =
    "<!-- Generated by user-memory from its store; do not edit, it is rewritten. -->";

/// What the agent must know before the rules: what they are, that each line
/// only points to a memory whose full text is read before following it, how
/// clients get another repository's rules and keep them loaded, and that the
/// user's preferences and project lessons are saved through user-memory, global
/// ones only with the user's yes.
const PREAMBLE: [&str; 17] = [
    "# USER MEMORY — the user's standing rules for every project",
    "Follow these unless the user or the current project says otherwise.",
    "Each line is a pointer, not the full memory. When a memory applies to what you are",
    "doing, read it first and follow its full text (conditions, exceptions, reason):",
    "user-memory `read` with its ids, all that apply in one call.",
    "Working in a repository and no user-memory index in context yet? Call user-memory",
    "`index` with projects: [<the repository's git remote>] for its rules too; with the",
    "session hooks, `link` each other repository you work in to keep it loaded.",
    "To save, change or forget anything about the user or their projects (a preference,",
    "decision, rule, or a lesson about a project's code that the repository does not",
    "state), use the user-memory MCP tools `record`, `update` and `forget`, with scope",
    "project for one repository (global only with the user's yes); load them first if",
    "your client has not. What every contributor needs, such as setup steps or",
    "conventions, is proposed to the user for the repository's AGENTS.md or docs, never",
    "edited unasked. Never put the user's preferences or project lessons in your client's",
    "own memory (Claude Code's MEMORY.md files under ~/.claude/projects, Codex's",
    "memories).",
];

/// Largest rules text unless the caller gives its room: Codex's 32 KiB limit
/// for all its instruction files together, less 8 KiB for the project's own
/// AGENTS.md files, so the limit never cuts these rules off.
pub const MAX_BYTES: usize = 24 * 1024;

/// The instruction-file text for the store at `db`, ending in a newline,
/// within `max_bytes` where counting categories can make it fit.
pub fn instructions(db: &Path, max_bytes: usize) -> Result<String> {
    let conn = connect(db)?;
    let global = Selection {
        scope: Some(ScopeFilter::Global),
        ..Selection::default()
    };
    let mut rules: Vec<Memory> = candidates(&conn, &global.filter()?, None)?
        .into_iter()
        .filter(standing_rule)
        .collect();
    rules.sort_by(group_order);
    Ok(render(
        max_bytes,
        rule_groups(rules)
            .into_iter()
            .map(|group| {
                let lines = group
                    .memories
                    .iter()
                    .map(|m| format!("- {}", neutral(line(m).trim_start())))
                    .collect();
                (neutral(&group.name), lines)
            })
            .collect(),
    ))
}

/// `text` with HTML comment openers and closers broken up, so no title or
/// category can open or close the marked block in Codex's file. The store
/// keeps the text as written.
fn neutral(text: &str) -> String {
    text.replace("<!--", "<!-\\-").replace("-->", "-\\->")
}

/// The text for `groups` (category, rule lines), largest categories counted
/// in one line each, while it is over `max_bytes`; every rule is listed or
/// counted.
fn render(max_bytes: usize, mut groups: Vec<(String, Vec<String>)>) -> String {
    let text = |groups: &[(String, Vec<String>)]| {
        let mut lines = vec![GENERATED.to_owned()];
        lines.extend(PREAMBLE.iter().map(|l| (*l).to_owned()));
        for (name, rules) in groups {
            lines.push(String::new());
            lines.push(name.clone());
            lines.extend(rules.iter().cloned());
        }
        lines.join("\n") + "\n"
    };
    let mut order: Vec<usize> = (0..groups.len()).collect();
    order.sort_by_key(|&g| std::cmp::Reverse(groups[g].1.len()));
    let mut rendered = text(&groups);
    for g in order {
        if rendered.len() <= max_bytes {
            break;
        }
        let (name, rules) = &mut groups[g];
        let noun = if rules.len() == 1 { "rule" } else { "rules" };
        *rules = vec![format!(
            "- {} {noun} — user-memory read(category=\"{name}\")",
            rules.len()
        )];
        rendered = text(&groups);
    }
    rendered
}

#[cfg(test)]
mod tests {
    use super::*;
    use uuid::Uuid;

    /// A store and a way to add a memory to it with any of its columns set.
    fn store() -> (tempfile::TempDir, std::path::PathBuf) {
        let dir = tempfile::tempdir().unwrap();
        let db = dir.path().join("memory.sqlite3");
        connect(&db).unwrap();
        (dir, db)
    }

    fn add(db: &Path, title: &str, set: &[(&str, &str)]) -> Uuid {
        let id = Uuid::new_v4();
        let conn = connect(db).unwrap();
        conn.execute(
            "INSERT INTO memories (id,memory_type,category,title,content,reason,context) VALUES (?1,'preference','workflow',?2,?2,'Because of a past incident','When releasing')",
            [id.to_string(), title.to_owned()],
        )
        .unwrap();
        for (column, value) in set {
            conn.execute(
                &format!("UPDATE memories SET {column}=?2 WHERE id=?1"),
                [id.to_string(), (*value).to_owned()],
            )
            .unwrap();
        }
        id
    }

    fn short(id: Uuid) -> String {
        id.to_string()[..8].to_owned()
    }

    #[test]
    fn only_confirmed_explicit_global_rules_are_listed_by_category() {
        let (_dir, db) = store();
        let push = add(&db, "Push only with the user's go-ahead", &[]);
        let attribution = add(
            &db,
            "No AI attribution in commits",
            &[("memory_type", "constraint")],
        );
        let magic = add(
            &db,
            "No magic values",
            &[("memory_type", "value"), ("category", "programming")],
        );
        add(&db, "Ship by Friday", &[("memory_type", "goal")]);
        add(
            &db,
            "Use Python here",
            &[("scope", "project"), ("project", "github.com/x/y")],
        );
        add(
            &db,
            "Prefers short replies",
            &[
                ("source", "observed"),
                ("status", "tentative"),
                ("evidence", "seen"),
            ],
        );
        add(&db, "Tentative rule", &[("status", "tentative")]);
        let old = add(&db, "Indent with tabs", &[]);
        let new = add(&db, "Indent with spaces", &[("category", "programming")]);
        connect(&db)
            .unwrap()
            .execute(
                "UPDATE memories SET status='superseded',superseded_by=?2 WHERE id=?1",
                [old.to_string(), new.to_string()],
            )
            .unwrap();
        let text = instructions(&db, MAX_BYTES).unwrap();
        // Categories largest first (ties by name), rules newest first, as the
        // index orders them.
        let body: Vec<&str> = text.lines().skip(1 + PREAMBLE.len()).collect();
        assert_eq!(
            body,
            [
                "".to_owned(),
                "programming".to_owned(),
                format!("- {} Indent with spaces", short(new)),
                format!("- {} No magic values", short(magic)),
                "".to_owned(),
                "workflow".to_owned(),
                format!("- {} No AI attribution in commits", short(attribution)),
                format!("- {} Push only with the user's go-ahead", short(push)),
            ],
            "{text}"
        );
        for leaked in [
            "Because of a past incident",
            "When releasing",
            "origin",
            "Ship",
            "Python",
            "short replies",
            "Tentative",
            "tabs",
        ] {
            assert!(!text.contains(leaked), "{leaked}: {text}");
        }
    }

    #[test]
    fn marker_text_in_a_rule_cannot_close_or_open_a_block() {
        let (_dir, db) = store();
        let title = "Write <!-- user-memory:end --> and <!-- user-memory:start --> literally";
        let id = add(&db, title, &[("category", "docs-->")]);
        let text = instructions(&db, MAX_BYTES).unwrap();
        let body = text.strip_prefix(GENERATED).unwrap();
        assert!(!body.contains("<!--") && !body.contains("-->"), "{text}");
        assert!(
            text.contains(&format!(
                "- {} Write <!-\\- user-memory:end -\\-> and <!-\\- user-memory:start -\\-> literally",
                short(id)
            )),
            "{text}"
        );
        assert!(text.contains("\ndocs-\\->\n"), "{text}");
        // The store keeps the title as written.
        let stored: String = connect(&db)
            .unwrap()
            .query_row(
                "SELECT title FROM memories WHERE id=?1",
                [id.to_string()],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(stored, title);
    }

    #[test]
    fn the_header_is_pinned_and_stands_alone_for_an_empty_store() {
        let (_dir, db) = store();
        let text = instructions(&db, MAX_BYTES).unwrap();
        assert_eq!(text, format!("{GENERATED}\n{}\n", PREAMBLE.join("\n")));
        assert!(text.contains("projects: [<the repository's git remote>]"));
        // The approved wording, wrapped across lines.
        assert!(text.replace('\n', " ").contains(
            "Each line is a pointer, not the full memory. When a memory applies to what you are doing, read it first and follow its full text (conditions, exceptions, reason): user-memory `read` with its ids, all that apply in one call."
        ));
        assert!(text.contains("use the user-memory MCP tools `record`, `update` and `forget`"));
    }

    #[test]
    fn a_large_rule_set_counts_its_largest_categories_and_drops_none() {
        let long = "r".repeat(110);
        let groups: Vec<(String, Vec<String>)> =
            [("workflow", 150), ("programming", 60), ("tools", 3)]
                .iter()
                .map(|(name, count)| {
                    (
                        (*name).to_owned(),
                        (0..*count).map(|i| format!("- {i:08x} {long}")).collect(),
                    )
                })
                .collect();
        let text = render(MAX_BYTES, groups.clone());
        assert!(text.len() <= MAX_BYTES, "{}", text.len());
        assert!(text.contains("workflow\n- 150 rules — user-memory read(category=\"workflow\")"));
        // The smaller categories still fit once the largest is counted.
        assert_eq!(text.matches(&long).count(), 63);
        // Less room counts the next largest too.
        let tight = render(8 * 1024, groups);
        assert!(tight.len() <= 8 * 1024, "{}", tight.len());
        assert!(
            tight.contains("programming\n- 60 rules — user-memory read(category=\"programming\")")
        );
        assert_eq!(tight.matches(&long).count(), 3);
        let under = render(
            MAX_BYTES,
            vec![("tools".into(), vec!["- 00000000 One".into()])],
        );
        assert!(under.ends_with("\ntools\n- 00000000 One\n"), "{under}");
    }

    #[test]
    fn the_header_sends_project_lessons_to_user_memory_and_shared_ones_to_the_repository() {
        let header = PREAMBLE.join(" ");
        for phrase in [
            "To save, change or forget anything about the user or their projects (a preference, decision, rule, or a lesson about a project's code that the repository does not state), use the user-memory MCP tools `record`, `update` and `forget`, with scope project for one repository (global only with the user's yes);",
            "What every contributor needs, such as setup steps or conventions, is proposed to the user for the repository's AGENTS.md or docs, never edited unasked.",
            "Never put the user's preferences or project lessons in your client's own memory (Claude Code's MEMORY.md files under ~/.claude/projects, Codex's memories).",
        ] {
            assert!(header.contains(phrase), "{phrase}");
        }
    }
}
